fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| {
         if c.is_ascii_lowercase() {
             // 'a'..'z' → 'A'..'Z'
             c.to_ascii_uppercase()
         } else if c.is_ascii_uppercase() {
             // 'A'..'Z' → 'a'..'z'
             c.to_ascii_lowercase()
         } else {
             // non‐ASCII‐letter → unchanged
             c
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_toggle_case() {
        assert_eq!(toggle_case(vec!['a', 'B', 'c', 'D']), vec!['A', 'b', 'C', 'd']);
        assert_eq!(toggle_case(vec!['x', 'Y', '1', '!', 'z']), vec!['X', 'y', '1', '!', 'Z']);
        assert_eq!(toggle_case(vec![]), Vec::<char>::new());
        // Non-ASCII characters remain unchanged
        assert_eq!(toggle_case(vec!['ñ', 'Ω', '中']), vec!['ñ', 'Ω', '中']);
    }
}